"use strict";
// Loads its formatter by a computed specifier while the module evaluates:
// the package runs in a Node island.
var util = require(["ut", "il"].join(""));
var stock = { salt: 500, rice: 2000 };

exports.find = function find(name) {
  return { label: util.format("%s", name).toUpperCase(), grams: stock[name] || 0 };
};
